package local.lito381.server;
import java.util.*;import java.lang.reflect.*;
/** Actual Snapshot producers/immutable siblings and detached restore constructors; no bound room/role/AI/IO. */
public final class SourceNpcFactoryMemoryPlan {
 static int cases;static void check(boolean b,String why){if(!b)throw new AssertionError(why);cases++;}
 static void set(Object o,String n,Object v)throws Exception{SourceSignedRecoveryPlan.set(o,n,v);}
 static Object copy(Object record,Object stamp,boolean extra)throws Exception{var parts=record.getClass().getRecordComponents();var types=new ArrayList<Class<?>>();var values=new ArrayList<Object>();for(var p:parts){types.add(p.getType());values.add(p.getAccessor().invoke(record));}if(extra){types.add(Object.class);values.add(stamp);}var ctor=record.getClass().getDeclaredConstructor(types.toArray(Class<?>[]::new));ctor.setAccessible(true);return ctor.newInstance(values.toArray());}
 static Object construct(String type,Object snapshot,BattleCompanion.Snapshot transferred)throws Exception{var cl=Class.forName("local.lito381.server."+type);var types=transferred==null?new Class<?>[]{snapshot.getClass()}:new Class<?>[]{snapshot.getClass(),BattleCompanion.Snapshot.class,List.class};var ctor=cl.getDeclaredConstructor(types);ctor.setAccessible(true);return ctor.newInstance(transferred==null?new Object[]{snapshot}:new Object[]{snapshot,transferred,List.of()});}
 static Object snapshot(Object actor)throws Exception{var m=actor.getClass().getDeclaredMethod("snapshot");m.setAccessible(true);return m.invoke(actor);}
 static Object evolvedProfile(BattleCompanion actor,int npc)throws Exception{var old=CombatAccess.field(actor,"profile");var parts=old.getClass().getRecordComponents();var types=Arrays.stream(parts).map(RecordComponent::getType).toArray(Class<?>[]::new);var values=new Object[parts.length];for(int i=0;i<parts.length;i++)values[i]=parts[i].getName().equals("npcId")?npc:parts[i].getAccessor().invoke(old);var ctor=old.getClass().getDeclaredConstructor(types);ctor.setAccessible(true);return ctor.newInstance(values);}
 public static void main(String[]args)throws Exception{
  var field=NativeDeNpcTemplateResources.class.getDeclaredField("current");field.setAccessible(true);var previous=field.get(null);try{var row=SourceCubeTemplatePlan.row(123);row.setImpl("L1Monster");row.set_undead(1);field.set(null,SourceCubeTemplatePlan.snapshot(Map.of(123,row),false));var arena=SourceNpcFactoryTypePlan.actor(777,BattleCompanion.Kind.ARENA);var original=NativeSourceNpcFactoryType.stamp(arena);var pet=SourceNpcFactoryTypePlan.actor(778,BattleCompanion.Kind.PET);var tamed=SourceNpcFactoryTypePlan.actor(779,BattleCompanion.Kind.TAMED);var ps=arena.snapshot();check(ps.nativeSourceNpcFactoryMemory==original&&NativeSourceNpcFactoryMemory.proof(ps)==original,"actual companion Snapshot producer carries exact immutable original birth value");var originalCopy=copy(ps,null,false);check(originalCopy.equals(ps)&&originalCopy.hashCode()==ps.hashCode()&&NativeSourceNpcFactoryMemory.proof(originalCopy)==null,"old canonical ctor/record equality/hash retain original schema and no invented metadata");var changedType=new NativeSourceNpcFactoryType.Stamp("different",123,"L1Door",4,3);var sibling=copy(ps,changedType,true);check(sibling.equals(ps)&&sibling.hashCode()==ps.hashCode()&&NativeSourceNpcFactoryMemory.proof(sibling)==changedType,"new immutable sibling preserves old identity/components while carrying a separate scalar proof");
   var quest=SourceSignedRecoveryPlan.unsafe().allocateInstance(Class.forName("local.lito381.server.BattleQuestEncounter$Monster"));set(quest,"template",SourceNpcFactoryTypePlan.template());set(quest,"objectId",888L);set(quest,"force",1);set(quest,"roomNumber",1);set(quest,"hp",1);set(quest,"placementSource","detached");set(quest,"nativeSourceNpcFactoryType",original);set(quest,"damagePoison",new BattleTimedStatus());var timed=SourceSignedRecoveryPlan.unsafe().allocateInstance(Class.forName("local.lito381.server.BattleTimeAttackEncounter$Monster"));for(var entry:Map.<String,Object>of("npcId",123,"objectId",889L,"gfx",1,"name","detached","level",1,"maxHp",100,"hp",1,"identitySource","detached","waveSource","detached").entrySet())set(timed,entry.getKey(),entry.getValue());set(timed,"nativeSourceNpcFactoryType",original);set(timed,"damagePoison",new BattleTimedStatus());var qs=snapshot(quest);var ts=snapshot(timed);check(NativeSourceNpcFactoryMemory.proof(qs)==original&&NativeSourceNpcFactoryMemory.proof(ts)==original,"actual Quest/Time Snapshot producers carry original scalar metadata");
   row.setImpl("L1Tower");row.set_undead(3);check(NativeSourceNpcFactoryMemory.proof(qs)==original&&NativeSourceNpcFactoryMemory.proof(ts)==original&&original.kind()==1&&original.undead()==1,"later static-template mutation cannot change original memory proofs");var qr=construct("BattleQuestEncounter$Monster",qs,null);var tr=construct("BattleTimeAttackEncounter$Monster",ts,null);check(NativeSourceNpcFactoryType.stamp(qr)==original&&NativeSourceNpcFactoryType.stamp(tr)==original,"actual Quest/Time restore constructors retain old class/undead after template reload");check(NativeSourceNpcFactoryMemory.proof(snapshot(qr))==original&&NativeSourceNpcFactoryMemory.proof(snapshot(tr))==original,"restored actors can be snapshotted again without losing original provenance");var transfer=tamed.snapshot();check(NativeSourceNpcFactoryMemory.proof(transfer).kind()==6,"actual transferred tame snapshot carries its own distinct controlled class");var qrelease=construct("BattleQuestEncounter$Monster",qs,transfer);var trelease=construct("BattleTimeAttackEncounter$Monster",ts,transfer);check(NativeSourceNpcFactoryType.stamp(qrelease)==original&&NativeSourceNpcFactoryType.stamp(trelease)==original,"release-tamed restore keeps primary natural actor class, not temporary controlled class");
   var fresh=SourceNpcFactoryTypePlan.actor(780,BattleCompanion.Kind.ARENA);check(NativeSourceNpcFactoryType.stamp(fresh).kind()==3,"fresh spawn remains a new birth and uses current static template");var newTarget=NativeSourceNpcFactoryType.stamp(fresh);var replacementSnapshot=copy(ts,newTarget,true);check(NativeSourceNpcFactoryType.stamp(construct("BattleTimeAttackEncounter$Monster",replacementSnapshot,null))==newTarget,"new replacement Snapshot provenance, rather than prior NPC class, survives reconstruction");
   field.set(null,null);var qNoTable=construct("BattleQuestEncounter$Monster",qs,null);var tNoTable=construct("BattleTimeAttackEncounter$Monster",ts,null);check(NativeSourceNpcFactoryType.stamp(qNoTable)==original&&NativeSourceNpcFactoryType.stamp(tNoTable)==original,"known memory restores do not require or load current resource snapshot");var legacyQ=copy(qs,null,false);var legacyT=copy(ts,null,false);check(NativeSourceNpcFactoryType.stamp(construct("BattleQuestEncounter$Monster",legacyQ,null))==null&&NativeSourceNpcFactoryType.stamp(construct("BattleTimeAttackEncounter$Monster",legacyT,null))==null,"legacy snapshots remain unqualified without current-template adoption");check(NativeSourceNpcFactoryType.stamp(construct("BattleQuestEncounter$Monster",legacyQ,transfer))==null&&NativeSourceNpcFactoryType.stamp(construct("BattleTimeAttackEncounter$Monster",legacyT,transfer))==null,"temporary controlled snapshot cannot promote an unknown primary natural origin");var wrong=new NativeSourceNpcFactoryType.Stamp("",124,"L1Monster",1,1);check(NativeSourceNpcFactoryMemory.proof(copy(qs,wrong,true))==null&&NativeSourceNpcFactoryType.stamp(construct("BattleQuestEncounter$Monster",copy(qs,wrong,true),null))==null,"same record with mismatched NPC id cannot carry another factory proof");check(NativeSourceNpcFactoryMemory.proof(copy(ts,new Object(),true))==null,"arbitrary extra metadata is not a factory proof");
   var oldPet=NativeSourceNpcFactoryType.stamp(pet);set(pet,"profile",evolvedProfile(pet,124));var evolved=pet.snapshot();var ep=NativeSourceNpcFactoryMemory.proof(evolved);check(ep!=null&&ep.npc()==124&&ep.kind()==5&&NativeSourceNpcFactoryType.stamp(pet)==oldPet&&oldPet.npc()==123,"actual pet snapshot adjusts evolved NPC id only through unchanged controlled class, without mutating birth proof");set(arena,"profile",evolvedProfile(arena,124));check(NativeSourceNpcFactoryMemory.proof(arena.snapshot())==null,"generic arena id change cannot invent an evolved class/template proof");
   for(Object record:List.of(ps,qs,ts)){var extra=record.getClass().getDeclaredField("nativeSourceNpcFactoryMemory");check(extra.getType()==Object.class&&Modifier.isFinal(extra.getModifiers())&&Modifier.isTransient(extra.getModifiers()),"Snapshot metadata is final/transient in-memory only");check(Arrays.stream(record.getClass().getRecordComponents()).noneMatch(c->c.getName().equals(extra.getName())),"record components and standard record serialization schema exclude scalar metadata");check(record.getClass().getRecordComponents().length==(record instanceof BattleCompanion.Snapshot?28:18),"all original Snapshot record component counts retained");}
   check(NativeSourceNpcFactoryMemory.class.getDeclaredFields().length==0&&NativeSourceNpcFactoryMemory.proof(new Object())==null,"helper has no actor/Frame/Context/row/snapshot registry or unsupported promotion");check(NativeSourceNpcFactoryType.delta(original,100)==-100&&NativeSourceNpcFactoryType.delta(newTarget,100)==0,"restored and fresh type values keep their distinct Source healing semantics");
  }finally{field.set(null,previous);}check(field.get(null)==previous,"original static snapshot restored after detached memory contracts");System.out.println("PASS"+cases+" NPC factory memory actual-Snapshot/sibling/restore/release-tamed/reload/evolved-pet/identity/transient-schema contracts; no bound restore/rollback/AI/HP/role/IO/Main/database/game qualification");
 }
}
